"use client"

import { type DragEvent, useRef, useState } from "react"
import Image from "next/image"
import {
  ApertureIcon,
  CheckIcon,
  PencilIcon,
  PlusIcon,
  UploadIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import type { VideoBuddyPageContent } from "@/components/mockups/contracts"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { imageGroupRadius } from "../image-grid-utils"
import { frameAt, storyboardFrames } from "../media-assets"
import { downloadMedia, MediaContextMenu } from "../media-context-menu"
import { ProjectPicker } from "../project-picker"

const characterProperties = [
  "Front",
  "Profile",
  "Three-quarter",
  "Full body",
  "Close-up",
  "Neutral",
  "Expression",
  "Outfit",
]

type Character = {
  id: number
  name: string
  images: number[]
  updated: string
  project: string
  frames: readonly string[]
}

const initialCharacters: Character[] = [
  {
    id: 3,
    name: "Mara",
    images: Array.from({ length: 18 }, (_, index) => index),
    updated: "Today, 1:48 PM",
    project: "Default project",
    frames: storyboardFrames.saltSignal,
  },
  {
    id: 2,
    name: "Eli",
    images: Array.from({ length: 12 }, (_, index) => index),
    updated: "Yesterday",
    project: "Default project",
    frames: storyboardFrames.afterHours,
  },
  {
    id: 1,
    name: "June",
    images: Array.from({ length: 8 }, (_, index) => index),
    updated: "Jul 21",
    project: "Default project",
    frames: storyboardFrames.blackTide,
  },
]

export function CharactersWorkspace({
  content,
}: {
  content: VideoBuddyPageContent
}) {
  const [characters, setCharacters] = useState(initialCharacters)
  const [editingId, setEditingId] = useState<number | null>(null)
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [isDragging, setIsDragging] = useState(false)
  const [characterName, setCharacterName] = useState("")
  const [uploadFiles, setUploadFiles] = useState<File[]>([])
  const [selectedImage, setSelectedImage] = useState<{
    characterId: number
    imageId: number
  } | null>(null)
  const [imageProperties, setImageProperties] = useState<
    Record<string, string[]>
  >({})
  const [projects, setProjects] = useState([
    "Default project",
    "Salt Signal",
    "Black Tide",
    "After Hours",
  ])
  const [projectTargetId, setProjectTargetId] = useState<number | null>(null)
  const [newProjectName, setNewProjectName] = useState("")
  const uploadRef = useRef<HTMLInputElement>(null)

  function renameCharacter(id: number, name: string) {
    setCharacters((current) =>
      current.map((character) =>
        character.id === id ? { ...character, name } : character
      )
    )
  }

  function setFiles(files: FileList | null) {
    if (!files?.length) return
    setUploadFiles(
      Array.from(files).filter((file) => file.type.startsWith("image/"))
    )
  }

  function createCharacter() {
    const name = characterName.trim()
    if (!name || uploadFiles.length === 0) return
    setCharacters((current) => [
      {
        id: (current[0]?.id ?? 0) + 1,
        name,
        images: Array.from({ length: uploadFiles.length }, (_, index) => index),
        updated: "Just now",
        project: "Default project",
        frames: storyboardFrames.saltSignal,
      },
      ...current,
    ])
    setCharacterName("")
    setUploadFiles([])
    setIsCreateOpen(false)
  }

  function handleDrop(event: DragEvent<HTMLDivElement>) {
    event.preventDefault()
    setIsDragging(false)
    setFiles(event.dataTransfer.files)
  }

  function toggleProperty(property: string) {
    if (!selectedImage) return
    const key = `${selectedImage.characterId}-${selectedImage.imageId}`
    setImageProperties((current) => {
      const properties = current[key] ?? []
      return {
        ...current,
        [key]: properties.includes(property)
          ? properties.filter((item) => item !== property)
          : [...properties, property],
      }
    })
  }

  return (
    <main className="flex h-[calc(100dvh-4rem)] flex-col overflow-hidden md:h-dvh">
      <section className="min-h-0 flex-1 overflow-y-auto overscroll-none">
        <div className="mx-auto max-w-6xl px-4 pb-10 sm:px-6">
          <header className="flex items-center justify-between gap-4 py-4">
            <h1 className="text-xl font-medium">{content.heading}</h1>
            <Button className="h-10 px-5" onClick={() => setIsCreateOpen(true)}>
              <PlusIcon className="size-6" />
              {content.primaryActionLabel}
            </Button>
          </header>

          {characters.map((character) => (
            <section key={character.id} className="py-6">
              <div className="mb-4 flex min-h-9 items-center justify-between gap-3">
                <div className="flex min-w-0 flex-wrap items-center gap-3">
                  {editingId === character.id ? (
                    <div className="flex min-w-0 flex-1 items-center gap-2">
                      <Input
                        value={character.name}
                        aria-label="Character name"
                        className="max-w-sm"
                        onChange={(event) =>
                          renameCharacter(character.id, event.target.value)
                        }
                        onKeyDown={(event) => {
                          if (event.key === "Enter") setEditingId(null)
                        }}
                        autoFocus
                      />
                      <Button
                        size="icon-sm"
                        variant="ghost"
                        aria-label="Save name"
                        onClick={() => setEditingId(null)}
                      >
                        <CheckIcon />
                      </Button>
                    </div>
                  ) : (
                    <>
                      <button
                        type="button"
                        className="group flex min-w-0 items-center gap-2"
                        onClick={() => setEditingId(character.id)}
                      >
                        <h2 className="truncate text-sm font-medium">
                          {character.name}
                        </h2>
                        <PencilIcon className="size-3.5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" />
                      </button>
                      <span className="text-xs text-muted-foreground">
                        {character.images.length} images · {character.updated}
                      </span>
                    </>
                  )}
                </div>
                <ProjectPicker
                  value={character.project}
                  projects={projects}
                  onChange={(project) =>
                    setCharacters((current) =>
                      current.map((item) =>
                        item.id === character.id ? { ...item, project } : item
                      )
                    )
                  }
                  onNew={() => setProjectTargetId(character.id)}
                />
              </div>

              <div className="grid grid-cols-6 gap-1.5 sm:grid-cols-9 md:grid-cols-12">
                {character.images.map((imageId, index) => (
                  <MediaContextMenu
                    key={imageId}
                    className={cn(
                      "relative aspect-square overflow-hidden bg-muted",
                      imageGroupRadius(index, character.images.length)
                    )}
                    onOpen={() =>
                      setSelectedImage({
                        characterId: character.id,
                        imageId,
                      })
                    }
                    openLabel="Open details"
                    onDownload={() =>
                      downloadMedia(
                        frameAt(character.frames, imageId + 1),
                        `${character.name}-reference-${index + 1}.webp`
                      )
                    }
                    onDuplicate={() =>
                      setCharacters((current) =>
                        current.map((item) =>
                          item.id === character.id
                            ? {
                                ...item,
                                images: [
                                  ...item.images.slice(0, index + 1),
                                  Math.max(...item.images) + 1,
                                  ...item.images.slice(index + 1),
                                ],
                              }
                            : item
                        )
                      )
                    }
                    duplicateLabel="Duplicate reference"
                    onRemove={() =>
                      setCharacters((current) =>
                        current.map((item) =>
                          item.id === character.id
                            ? {
                                ...item,
                                images: item.images.filter(
                                  (itemImageId) => itemImageId !== imageId
                                ),
                              }
                            : item
                        )
                      )
                    }
                    removeLabel="Remove reference"
                  >
                    <button
                      type="button"
                      aria-label={`Open ${character.name} reference ${imageId + 1}`}
                      onClick={() =>
                        setSelectedImage({
                          characterId: character.id,
                          imageId,
                        })
                      }
                      className="group relative size-full outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <Image
                        src={frameAt(character.frames, imageId + 1)}
                        alt=""
                        fill
                        className={cn(
                          "object-cover transition-transform group-hover:scale-105",
                          imageId % 4 === 1 && "hue-rotate-15",
                          imageId % 4 === 2 && "saturate-50",
                          imageId % 4 === 3 && "contrast-125"
                        )}
                      />
                    </button>
                  </MediaContextMenu>
                ))}
                <label
                  className={cn(
                    "flex aspect-square items-center justify-center border border-dashed text-muted-foreground transition-colors hover:bg-muted hover:text-foreground",
                    "rounded-md"
                  )}
                >
                  <PlusIcon className="size-4" />
                  <span className="sr-only">
                    Add reference images to {character.name}
                  </span>
                  <input
                    type="file"
                    accept="image/*"
                    multiple
                    className="sr-only"
                    onChange={(event) => {
                      const count = event.target.files?.length ?? 0
                      setCharacters((current) =>
                        current.map((item) =>
                          item.id === character.id
                            ? {
                                ...item,
                                images: [
                                  ...item.images,
                                  ...Array.from(
                                    { length: count },
                                    (_, index) =>
                                      Math.max(-1, ...item.images) + 1 + index
                                  ),
                                ],
                              }
                            : item
                        )
                      )
                    }}
                  />
                </label>
              </div>
            </section>
          ))}
        </div>
      </section>

      {characters.length === 0 && (
        <div className="flex flex-1 flex-col items-center justify-center gap-2 text-center">
          <ApertureIcon className="size-5 text-muted-foreground" />
          <p className="text-sm font-medium">{content.emptyStateTitle}</p>
        </div>
      )}

      <Dialog
        open={isCreateOpen}
        onOpenChange={(open) => {
          setIsCreateOpen(open)
          if (!open) {
            setIsDragging(false)
            setCharacterName("")
            setUploadFiles([])
          }
        }}
      >
        <DialogContent className="gap-5 rounded-2xl sm:max-w-xl">
          <DialogHeader>
            <DialogTitle>New character</DialogTitle>
            <DialogDescription>
              Name the character and add reference images.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-2">
            <label htmlFor="character-name" className="text-sm font-medium">
              Name
            </label>
            <Input
              id="character-name"
              value={characterName}
              onChange={(event) => setCharacterName(event.target.value)}
              placeholder="Character name"
              autoFocus
            />
          </div>

          <div
            onDragEnter={(event) => {
              event.preventDefault()
              setIsDragging(true)
            }}
            onDragOver={(event) => event.preventDefault()}
            onDragLeave={(event) => {
              if (!event.currentTarget.contains(event.relatedTarget as Node)) {
                setIsDragging(false)
              }
            }}
            onDrop={handleDrop}
            className={cn(
              "flex min-h-64 cursor-pointer flex-col items-center justify-center rounded-xl border border-dashed border-border px-6 text-center transition-colors hover:bg-muted",
              isDragging && "bg-muted"
            )}
            onClick={() => uploadRef.current?.click()}
            role="button"
            tabIndex={0}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault()
                uploadRef.current?.click()
              }
            }}
          >
            <UploadIcon className="size-6 text-muted-foreground" />
            <p className="mt-3 text-sm font-medium">
              {uploadFiles.length > 0
                ? `${uploadFiles.length} image${uploadFiles.length === 1 ? "" : "s"} selected`
                : "Drop character images here"}
            </p>
            <p className="mt-1 text-xs text-muted-foreground">
              or click to choose files
            </p>
            <input
              ref={uploadRef}
              type="file"
              accept="image/*"
              multiple
              className="sr-only"
              onChange={(event) => setFiles(event.target.files)}
            />
          </div>

          <Button
            onClick={createCharacter}
            disabled={!characterName.trim() || uploadFiles.length === 0}
          >
            Create character
          </Button>
        </DialogContent>
      </Dialog>

      <Dialog
        open={selectedImage !== null}
        onOpenChange={(open) => {
          if (!open) setSelectedImage(null)
        }}
      >
        <DialogContent className="max-h-[calc(100dvh-2rem)] gap-0 overflow-hidden rounded-2xl p-0 sm:max-w-4xl">
          <DialogHeader className="sr-only">
            <DialogTitle>Character reference</DialogTitle>
            <DialogDescription>
              Review this reference and assign character properties.
            </DialogDescription>
          </DialogHeader>
          {selectedImage && (
            <div className="grid min-h-0 overflow-y-auto md:grid-cols-[minmax(0,1fr)_300px]">
              <div className="flex min-h-80 items-center bg-background">
                <div className="relative aspect-square max-h-[70dvh] w-full">
                  <Image
                    src={frameAt(
                      characters.find(
                        (character) =>
                          character.id === selectedImage.characterId
                      )?.frames ?? storyboardFrames.saltSignal,
                      selectedImage.imageId + 1
                    )}
                    alt="Character reference"
                    fill
                    className={cn(
                      "object-cover",
                      selectedImage.imageId % 4 === 1 && "hue-rotate-15",
                      selectedImage.imageId % 4 === 2 && "saturate-50",
                      selectedImage.imageId % 4 === 3 && "contrast-125"
                    )}
                    priority
                  />
                </div>
              </div>
              <aside className="bg-background p-5 sm:p-6">
                <div className="pr-10">
                  <p className="text-sm font-medium">
                    {
                      characters.find(
                        (character) =>
                          character.id === selectedImage.characterId
                      )?.name
                    }
                  </p>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Reference image {selectedImage.imageId + 1}
                  </p>
                </div>
                <div className="mt-8">
                  <p className="mb-3 text-xs font-medium text-muted-foreground">
                    Properties
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {characterProperties.map((property) => {
                      const key = `${selectedImage.characterId}-${selectedImage.imageId}`
                      const isSelected = (imageProperties[key] ?? []).includes(
                        property
                      )
                      return (
                        <Button
                          key={property}
                          type="button"
                          size="sm"
                          variant={isSelected ? "secondary" : "outline"}
                          aria-pressed={isSelected}
                          onClick={() => toggleProperty(property)}
                        >
                          {property}
                        </Button>
                      )
                    })}
                  </div>
                </div>
              </aside>
            </div>
          )}
        </DialogContent>
      </Dialog>

      <Dialog
        open={projectTargetId !== null}
        onOpenChange={(open) => {
          if (!open) {
            setProjectTargetId(null)
            setNewProjectName("")
          }
        }}
      >
        <DialogContent className="gap-5 rounded-2xl sm:max-w-md">
          <DialogHeader>
            <DialogTitle>New project</DialogTitle>
            <DialogDescription>
              Create and assign a project to this character.
            </DialogDescription>
          </DialogHeader>
          <Input
            value={newProjectName}
            onChange={(event) => setNewProjectName(event.target.value)}
            placeholder="Project name"
            aria-label="Project name"
            autoFocus
          />
          <Button
            disabled={!newProjectName.trim()}
            onClick={() => {
              const project = newProjectName.trim()
              if (!project || projectTargetId === null) return
              setProjects((current) =>
                current.includes(project) ? current : [...current, project]
              )
              setCharacters((current) =>
                current.map((item) =>
                  item.id === projectTargetId ? { ...item, project } : item
                )
              )
              setProjectTargetId(null)
              setNewProjectName("")
            }}
          >
            Create project
          </Button>
        </DialogContent>
      </Dialog>
    </main>
  )
}

const assetRoot = "/generated/2026-07-24-004043"
const slugGangAssetRoot = "/generated/2026-07-24-142500-slug-gang"

export const storyMedia = {
  saltSignal: {
    wide: `${assetRoot}/salt-signal-wide.webp`,
    character: `${assetRoot}/mara-portrait.webp`,
  },
  blackTide: {
    wide: `${assetRoot}/black-tide-wide.webp`,
    character: `${assetRoot}/june-portrait.webp`,
  },
  afterHours: {
    wide: `${assetRoot}/after-hours-wide.webp`,
    character: `${assetRoot}/eli-portrait.webp`,
  },
} as const

export const storyboardFrames = {
  slugGang: [
    `${slugGangAssetRoot}/scene-01.png`,
    `${slugGangAssetRoot}/scene-02.png`,
    `${slugGangAssetRoot}/scene-03.png`,
    `${slugGangAssetRoot}/scene-04.png`,
    `${slugGangAssetRoot}/scene-05.png`,
    `${slugGangAssetRoot}/scene-06.png`,
    `${slugGangAssetRoot}/scene-07.png`,
    `${slugGangAssetRoot}/scene-08.png`,
  ],
  saltSignal: [
    storyMedia.saltSignal.wide,
    storyMedia.saltSignal.character,
    storyMedia.saltSignal.wide,
    storyMedia.saltSignal.wide,
  ],
  blackTide: [
    storyMedia.blackTide.wide,
    storyMedia.blackTide.character,
    storyMedia.blackTide.wide,
    storyMedia.blackTide.character,
  ],
  afterHours: [
    storyMedia.afterHours.wide,
    storyMedia.afterHours.character,
    storyMedia.afterHours.wide,
    storyMedia.afterHours.character,
  ],
} as const

export function frameAt(frames: readonly string[], index: number) {
  return frames[index % frames.length]
}

export function framesForName(name: string) {
  const normalized = name.toLowerCase()
  if (normalized.includes("tide") || normalized.includes("june")) {
    return storyboardFrames.blackTide
  }
  if (
    normalized.includes("after") ||
    normalized.includes("rehearsal") ||
    normalized.includes("eli")
  ) {
    return storyboardFrames.afterHours
  }
  return storyboardFrames.saltSignal
}

"use client"

import type { ComponentProps, ReactNode } from "react"
import {
  ArrowDownToLineIcon,
  CopyIcon,
  ExternalLinkIcon,
  RotateCwIcon,
  Trash2Icon,
} from "lucide-react"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"
import { cn } from "@/lib/utils"

type MediaContextMenuProps = {
  children: ReactNode
  className?: string
  triggerProps?: Omit<ComponentProps<"div">, "children" | "className">
  onOpen?: () => void
  openLabel?: string
  onDownload?: () => void
  onDuplicate?: () => void
  duplicateLabel?: string
  onRemove?: () => void
  removeLabel?: string
}

export function MediaContextMenu({
  children,
  className,
  triggerProps,
  onOpen,
  openLabel = "Open",
  onDownload,
  onDuplicate,
  duplicateLabel = "Duplicate",
  onRemove,
  removeLabel = "Remove",
}: MediaContextMenuProps) {
  return (
    <ContextMenu>
      <ContextMenuTrigger
        className={cn("min-w-0", className)}
        {...triggerProps}
      >
        {children}
      </ContextMenuTrigger>
      <ContextMenuContent>
        {onOpen && (
          <ContextMenuItem onClick={onOpen}>
            <ExternalLinkIcon />
            {openLabel}
          </ContextMenuItem>
        )}
        {onDownload && (
          <ContextMenuItem onClick={onDownload}>
            <ArrowDownToLineIcon />
            Download
          </ContextMenuItem>
        )}
        {onDuplicate && (
          <ContextMenuItem onClick={onDuplicate}>
            {duplicateLabel.toLowerCase().includes("reroll") ? (
              <RotateCwIcon />
            ) : (
              <CopyIcon />
            )}
            {duplicateLabel}
          </ContextMenuItem>
        )}
        {onRemove && (
          <>
            <ContextMenuSeparator />
            <ContextMenuItem variant="destructive" onClick={onRemove}>
              <Trash2Icon />
              {removeLabel}
            </ContextMenuItem>
          </>
        )}
      </ContextMenuContent>
    </ContextMenu>
  )
}

export function downloadMedia(url: string, filename: string) {
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = filename
  anchor.click()
}

"use client"

import { ChevronDownIcon, PlusIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

export function ProjectPicker({
  value,
  projects,
  onChange,
  onNew,
}: {
  value: string
  projects: string[]
  onChange: (project: string) => void
  onNew: () => void
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant="ghost" size="sm" className="max-w-44" />}
      >
        <span className="truncate">{value}</span>
        <ChevronDownIcon />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Project</DropdownMenuLabel>
          {projects.map((project) => (
            <DropdownMenuItem
              key={project}
              onClick={() => onChange(project)}
            >
              {project}
            </DropdownMenuItem>
          ))}
          <DropdownMenuItem onClick={onNew}>
            <PlusIcon />
            New project
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

